<?php require_once __DIR__.'/../core.php'; require_once __DIR__.'/auth.php'; $items=data_list('auctions'); if($_SERVER['REQUEST_METHOD']==='POST'){if(geah_media_post($items,'auctions')){data_save('auctions',$items);header('Location:/admin/auctions.php');exit;} if(isset($_POST['delete'])){$id=(int)$_POST['delete'];$items=array_values(array_filter($items,fn($x)=>($x['id']??0)!=$id));}else{$new=['id'=>time(),'date'=>now()];$new['title']=$_POST['title']??'';$new['city']=$_POST['city']??'';$new['start_price']=$_POST['start_price']??'';$new['current_price']=$_POST['current_price']??'';$new['end_date']=$_POST['end_date']??'';$new['status']=$_POST['status']??'';$new['description']=$_POST['description']??'';$new['images']=geah_upload_files('photos','auctions',['jpg','jpeg','png','webp','gif']);$gv=geah_upload_files('video_file','auctions',['mp4','webm','mov','ogg']);$new['video_url']=$gv[0]??trim($_POST['video_url']??'');$items[]=$new;} data_save('auctions',$items); header('Location:/admin/auctions.php'); exit;} ?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/style.css?v=110"></head><body><div class="admin-layout"><?php include __DIR__.'/sidebar.php'; ?><main class="admin-main"><h1>Vente aux enchères</h1><p style="color:#6b7280;font-size:13px">📌 Ajoute les photos directement sur chaque élément, dans la section « Photos & vidéos » plus bas. 👇</p><form class="card" method="post" enctype="multipart/form-data"><div class="form-grid"><label>Bien<input type="text" name="title"></label><label>Ville<input type="text" name="city"></label><label>Prix départ<input type="number" name="start_price"></label><label>Prix actuel<input type="number" name="current_price"></label><label>Date fin<input type="date" name="end_date"></label><label>Statut<select name="status"><option>En attente</option><option>En cours</option><option>Terminée</option><option>Annulée</option></select></label><label class="full">Description<textarea name="description" rows="4"></textarea></label><label>📷 Photos (plusieurs)<input type="file" name="photos[]" accept="image/*" multiple></label><label>🎬 Vidéo<input type="file" name="video_file" accept="video/*"></label><label>… ou lien vidéo<input type="text" name="video_url" placeholder="YouTube..."></label></div><button class="btn btn-primary">Ajouter</button></form><table class="table"><tr><th>ID</th><th>Bien</th><th>Ville</th><th>Prix départ</th><th>Prix actuel</th><th>Date fin</th><th>Statut</th><th>Description</th><th></th></tr><?php foreach(array_reverse($items) as $item): ?><tr><td><?=e($item['id']??'')?></td><td><?=e($item['title']??'')?></td><td><?=e($item['city']??'')?></td><td><?=e($item['start_price']??'')?></td><td><?=e($item['current_price']??'')?></td><td><?=e($item['end_date']??'')?></td><td><?=e($item['status']??'')?></td><td><?=e($item['description']??'')?></td><td><form method="post"><button class="btn danger" name="delete" value="<?=e($item['id'])?>">Supprimer</button></form></td></tr><?php endforeach; ?></table><h2>📷 Photos & vidéos par élément</h2><?php foreach(array_reverse($items) as $item): ?><div class="card"><h3><?=e($item['title']??'')?></h3><?=geah_media_block($item)?></div><?php endforeach; ?></main></div><script>
(function(){const saved=localStorage.getItem('geah_theme')||'dark';if(saved==='light')document.body.classList.add('light-mode');function ready(){const btn=document.createElement('button');btn.className='theme-toggle';function label(){btn.textContent=document.body.classList.contains('light-mode')?'🌙 Mode sombre':'☀️ Mode clair'}btn.onclick=function(){document.body.classList.toggle('light-mode');localStorage.setItem('geah_theme',document.body.classList.contains('light-mode')?'light':'dark');label()};label();document.body.appendChild(btn)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);else ready();})();
</script></body></html>